describe('Active Filter Tags Display', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display active filter tags above search results when multiple filters are applied', () => {
    // Setup: Apply multiple filters
    cy.get('[data-testid="filter-checkbox-category"]').click();
    cy.get('[data-testid="filter-checkbox-price"]').click();
    cy.get('[data-testid="filter-checkbox-brand"]').click();

    // Verify filter checkboxes are checked
    cy.get('[data-testid="filter-checkbox-category"]').should('be.checked');
    cy.get('[data-testid="filter-checkbox-price"]').should('be.checked');
    cy.get('[data-testid="filter-checkbox-brand"]').should('be.checked');

    // Verify filter tags are visible and contain correct values
    cy.get('[data-testid="filter-tag-container"]').should('be.visible');
    cy.get('[data-testid="filter-tag-category"]').should('contain', 'Category');
    cy.get('[data-testid="filter-tag-price"]').should('contain', 'Price');
    cy.get('[data-testid="filter-tag-brand"]').should('contain', 'Brand');

    // Verify filter tags are styled as expected
    cy.get('[data-testid="filter-tag-category"]').should('have.css', 'color', 'blue');
    cy.get('[data-testid="filter-tag-price"]').should('have.css', 'color', 'green');
    cy.get('[data-testid="filter-tag-brand"]').should('have.css', 'color', 'red');

    // Verify search results are displayed with applied filters
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Verify filter tags are above search results
    cy.get('[data-testid="filter-tag-container"]').should('be.above', '[data-testid="search-results"]');
  });

  it('should hide filter tags when no filters are applied', () => {
    // Setup: Clear all filters
    cy.get('[data-testid="filter-checkbox-category"]').click();
    cy.get('[data-testid="filter-checkbox-price"]').click();
    cy.get('[data-testid="filter-checkbox-brand"]').click();

    // Verify filter checkboxes are checked
    cy.get('[data-testid="filter-checkbox-category"]').should('be.checked');
    cy.get('[data-testid="filter-checkbox-price"]').should('be.checked');
    cy.get('[data-testid="filter-checkbox-brand"]').should('be.checked');

    // Clear filters
    cy.get('[data-testid="filter-checkbox-category"]').click();
    cy.get('[data-testid="filter-checkbox-price"]').click();
    cy.get('[data-testid="filter-checkbox-brand"]').click();

    // Verify filter tags are hidden
    cy.get('[data-testid="filter-tag-container"]').should('not.exist');

    // Verify search results are displayed without filter tags
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);
  });
});
